// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    address creator = address(0x1);

    function setUp() public {
        vm.prank(creator);
        c = new Wallet();
        vm.deal(creator, 100 ether);
        vm.prank(creator);
        c.deposit{value: 10 ether}();
    }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != creator);
        vm.assume(amount <= 10 ether);
        uint256 balBefore = address(c).balance;
        vm.prank(caller);
        try c.migrateTo(address(0xdead)) { } catch { }
        uint256 balAfter = address(c).balance;
        assertEq(balAfter, balBefore);
    }
}
